def get_modules_phase5():
    modules = [{'phase_slug': 'phase-5-specialization-capstone', 'module_number': 12, 'slug': 'multimodal-ai-and-vision', 'real_world_deliverable': 'Multimodal Document & Video Intelligence Engine with Visual Grounding', 'zero_gpu_recipe': {'platform': 'Google AI Studio (Gemini 2.0 Flash) / Colab Free T4', 'vram_required': '0 GB (via Gemini API) / 8 GB (Local Moondream / Florence-2)', 'estimated_cost': '$0.00 Free', 'compute_units_tip': 'Gemini 2.0 Flash on Google AI Studio provides 1,500 free multimodal requests per day with 1M context for video, audio and image processing.', 'one_click_command': 'pip install google-genai pillow opencv-python transformers'}, 'title': 'Module 12: Multimodal AI & Vision', 'weeks_range': 'Weeks 17-18', 'estimated_hours': 16, 'learning_outcomes': ['Foundations of Vision-Language Models (VLMs): CLIP contrastive learning aur joint embedding spaces', 'Vision Encoders & Cross-Attention Projectors: SigLIP, Linear projection vs MLP projection aur LLaVA architecture', 'Document & Invoice OCR Intelligence: Visual table extraction, bounding boxes aur key-value parsing', 'Audio & Speech AI: Whisper acoustic features, Mel-spectrograms, CTC loss aur audio-LLM tokenization', 'Video understanding: Keyframe sampling, temporal attention mechanisms aur video question answering', 'End-to-end multimodal agent pipelines integrating images, diagrams, audio transcripts aur text'], 'practical_tasks': ['CLIP zero-shot image classification aur visual search engine implement karein', 'Florence-2 / Moondream VLM use karke invoices aur receipts se structured JSON extract karein', 'Whisper model se Roman Urdu audio speech ko stream aur transcribe karein', 'OpenCV video frame extraction pipeline build karein for temporal video search', 'Multimodal RAG pipeline design karein jo PDF ke diagrams aur tables ko visually retrieve kare'], 'resources': [{'title': 'OpenAI CLIP: Learning Transferable Visual Models', 'url': 'https://arxiv.org/abs/2103.00020'}, {'title': 'LLaVA: Visual Instruction Tuning', 'url': 'https://llava-vl.github.io/'}, {'title': 'Google SigLIP: Sigmoid Loss for Language Image Pre-Training', 'url': 'https://arxiv.org/abs/2303.15343'}, {'title': 'OpenAI Whisper Speech Recognition', 'url': 'https://github.com/openai/whisper'}], 'diagram_script': '@preset midnight\n@animate flow\nflow LR: Module 12 Multimodal Architecture\n  img[Visual Input: Image / Video Frame] $browser -> vis_enc[Vision Encoder: SigLIP / ViT] $cpu\n  vis_enc -> proj[Linear / MLP Projector] $layers\n  audio[Audio Input: Speech WAV] $terminal -> whisper[Whisper Encoder] $cpu\n  proj & whisper -> llm[Multimodal LLM Backbone] $brain *\n  llm -> out[Structured Visual Analysis & Grounding] $server', 'diagram_preset': 'midnight', 'diagram_animation': 'flow', 'badge_slug': 'ai-graduate', 'order_index': 12, 'lessons': [{'lesson_code': '12.1', 'slug': 'vision-language-foundations-clip', 'title': 'Foundations of Vision-Language Models: CLIP & Contrastive Learning', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, 2021 se pehle Computer Vision aur NLP do bilkul alag alag jaziray (islands) the! Computer Vision models (ResNet, EfficientNet) 1,000 fixed ImageNet classes predict karte the, jabke NLP models text par kaam karte the.\n\nOpenAI ke **CLIP (Contrastive Language-Image Pre-training)** ne in dono dunyaon ko hamesha ke liye mila diya!\nCLIP ka core concept bohot khubsurat hai: **Contrastive Learning in a Shared Joint Embedding Space**.\nCLIP kaise train hota hai?\n1. 400 Million (Image, Text Caption) pairs internet se liye gaye.\n2. Image ko ek **Vision Encoder** (ViT ya ResNet) se pass karke vector $I_i$ banaya jata hai ($d=512$).\n3. Text caption ko ek **Text Encoder** (Transformer) se pass karke vector $T_j$ banaya jata ($d=512$).\n4. Ek batch mein $N$ images aur $N$ texts hote hain ($N \\times N$ similarity matrix).\n5. Loss function (InfoNCE / Symmetric Cross Entropy) ka target yeh hota hai ke diagonal elements ($I_i \\cdot T_i$) ki cosine similarity maximum ho (close to 1), aur non-diagonal elements ($I_i \\cdot T_j$) ki similarity 0 ke qareeb ho!\n\nIska jadu: CLIP bina kisi training ke **Zero-Shot Classifier** ban jata hai! Aap prompt likhein "A photo of a Lahori samosa" aur CLIP lakhon images mein se samosa dhoond kar nikal lega!', 'english_summary': "Understand OpenAI CLIP's contrastive learning objective (InfoNCE), dual-encoder architecture, shared vector embedding space, and zero-shot visual classification.", 'code_example': 'import torch\nimport torch.nn.functional as F\n\ndef clip_contrastive_loss(image_embeddings: torch.Tensor, text_embeddings: torch.Tensor, temperature: float = 0.07):\n    """Calculates symmetric CLIP contrastive InfoNCE loss across a batch of N pairs."""\n    # 1. Normalize embeddings to unit hypersphere\n    image_norm = F.normalize(image_embeddings, p=2, dim=-1)\n    text_norm = F.normalize(text_embeddings, p=2, dim=-1)\n    \n    # 2. Compute cosine similarity matrix (N x N) scaled by temperature\n    logits = torch.matmul(image_norm, text_norm.t()) / temperature\n    \n    # 3. Ground truth targets: Diagonal elements (i == j)\n    labels = torch.arange(len(image_embeddings), device=image_embeddings.device)\n    \n    # 4. Symmetric cross-entropy loss (Image-to-Text and Text-to-Image)\n    loss_img = F.cross_entropy(logits, labels)\n    loss_txt = F.cross_entropy(logits.t(), labels)\n    return (loss_img + loss_txt) / 2.0\n\n# Batch of 4 images and 4 matching text captions\nimg_vecs = torch.randn(4, 512)\ntxt_vecs = torch.randn(4, 512)\nloss = clip_contrastive_loss(img_vecs, txt_vecs)\nprint(f"Computed CLIP Contrastive Loss: {loss.item():.4f}")', 'diagram_script': '@preset midnight\n@animate flow\nflow LR: CLIP Joint Contrastive Embedding Space\n  img[Image Input] $browser -> img_enc[Vision Encoder ViT] $cpu\n  txt[Text Caption] $terminal -> txt_enc[Text Encoder Transformer] $cpu\n  img_enc -> img_vec[Normalized Image Vector I] $layers\n  txt_enc -> txt_vec[Normalized Text Vector T] $layers\n  img_vec & txt_vec -> mat[N x N Cosine Similarity Matrix] $database *\n  mat -> loss[InfoNCE Loss: Maximize Diagonal Matches] $brain', 'diagram_type': 'flow', 'resources': [{'title': 'CLIP Paper (Radford et al., 2021)', 'url': 'https://arxiv.org/abs/2103.00020'}, {'title': 'OpenCLIP Implementation', 'url': 'https://github.com/mlfoundations/open_clip'}], 'xp_reward': 25, 'order_index': 1}, {'lesson_code': '12.2', 'slug': 'cross-attention-projectors-siglip', 'title': 'Vision Encoders & Projectors: SigLIP & Modern VLM Architecture', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, modern Vision-Language Models (jaise LLaVA, Qwen2-VL, aur Gemini) CLIP ke dual encoders se aage nikal chuke hain. Wo images ko sirf classify nahi karte balki images ke baare mein insani rawani ke sath guftagu karte hain!\n\nModern VLM ka architecture teen ahem hisson par mushtamil hota hai:\n1. **Vision Encoder (SigLIP / ViT)**:\n   Google ka **SigLIP (Sigmoid Loss for Language Image Pre-training)** standard Softmax ki jagah simple pairwise sigmoid loss use karta hai, jis se batch size normalization ki zaroorat khatam ho jati hai aur vision features bohot rich bante hain.\n2. **Cross-Modal Projector**:\n   Vision encoder image ko 16x16 patches mein tod kar har patch ka vector banata hai (maslan 576 tokens, har token dimension 1024). Lekin LLM ka input dimension 4096 hota hai!\n   Is mismatch ko bridge karne ke liye ek **Projector** (2-layer MLP with GELU activation) use hota hai jo image tokens ko LLM ke text embedding space mein translate karta hai!\n3. **Autoregressive LLM Backbone**:\n   LLM ke liye image tokens bilkul aam text tokens ki tarah ban jate hain! System prompt + Image Tokens + User Query ek single sequence mein concatenate ho kar LLM ke attention blocks se guzar kar answer generate karte hain.', 'english_summary': 'Architect modern Vision-Language Models (VLMs) utilizing SigLIP vision backbones and MLP cross-modal projectors to map 2D image patch tokens directly into LLM embedding space.', 'code_example': 'import torch\nimport torch.nn as nn\n\nclass VisionProjector(nn.Module):\n    """2-Layer MLP Cross-Modal Projector (LLaVA-1.5 Style)."""\n    def __init__(self, vision_dim: int = 1024, llm_dim: int = 4096):\n        super().__init__()\n        self.linear1 = nn.Linear(vision_dim, llm_dim)\n        self.act = nn.GELU()\n        self.linear2 = nn.Linear(llm_dim, llm_dim)\n        \n    def forward(self, visual_tokens: torch.Tensor) -> torch.Tensor:\n        # Input shape: [batch, num_patches (e.g. 576), vision_dim]\n        # Output shape: [batch, num_patches, llm_dim]\n        return self.linear2(self.act(self.linear1(visual_tokens)))\n\n# Simulate 576 image patch tokens coming from SigLIP ViT-SO400M\nprojector = VisionProjector(vision_dim=1024, llm_dim=4096)\nraw_patches = torch.randn(1, 576, 1024)\nprojected_tokens = projector(raw_patches)\n\nprint(f"Raw visual patch tokens: {raw_patches.shape}")\nprint(f"Projected tokens ready for LLM attention: {projected_tokens.shape}")', 'diagram_script': "@preset midnight\n@animate flow\nflow LR: Modern VLM (LLaVA) Architecture\n  image[Input Image 336x336] $browser -> vit[SigLIP ViT Vision Encoder] $cpu\n  vit -> patches[576 Visual Patch Tokens 1024-d] $layers\n  patches -> mlp[2-Layer MLP Projector] $server *\n  mlp -> llm_tokens[Visual Tokens in 4096-d LLM Space] $database\n  prompt[User Prompt: 'Describe chart'] $terminal -> tokenizer[Text Tokenizer] $code\n  tokenizer & llm_tokens -> llm[LLM Backbone Llama / Mistral] $brain\n  llm -> output[Text Response Stream] $terminal", 'diagram_type': 'flow', 'resources': [{'title': 'SigLIP Research Paper', 'url': 'https://arxiv.org/abs/2303.15343'}, {'title': 'LLaVA Architecture Overview', 'url': 'https://github.com/haotian-liu/LLaVA'}], 'xp_reward': 25, 'order_index': 2}, {'lesson_code': '12.3', 'slug': 'document-invoice-ocr-donut', 'title': 'Document & Invoice Intelligence: Visual OCR & Structured Extraction', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, real-world enterprise applications mein sab se aam problem PDFs, scanned receipts, utility bills, aur complex tabular financial invoices ko parse karna hota hai.\n\nPurana tarika kya tha?\n1. Pehle Tesseract OCR se ganda text extract karo (jisme columns aur layout mess up ho jate the).\n2. Phir mushkil Regex likho jo har invoice format ke change hone par phat jata tha!\n\nModern AI approach **OCR-free Visual Document Intelligence** hai (jaise Microsoft Florence-2, Donut, aur Gemini 2.0 Flash):\n- Model direct image ke pixels ko dekhta hai.\n- Yeh spatial relationships ko samajhta hai (maslan: "Total Amount" ke theek samne ya neechay likha hua number hi total hai chahe koi divider line na ho).\n- Direct **Pydantic Structured JSON** output produce karta hai jisme invoice number, line items, tax rate, aur total amounts verified format mein milte hain.', 'english_summary': 'Extract structured data from complex invoices, receipts, and tabular PDFs using end-to-end Visual Document Models without brittle OCR preprocessing.', 'code_example': 'from pydantic import BaseModel, Field\nfrom typing import List\n\n# 1. Define Strict Pydantic Schema for Invoice Extraction\nclass LineItem(BaseModel):\n    description: str = Field(description="Item name or service rendered")\n    quantity: int = Field(description="Quantity purchased")\n    unit_price: float = Field(description="Price per unit in PKR or USD")\n    total_price: float = Field(description="Total price for this line item")\n\nclass InvoiceData(BaseModel):\n    invoice_number: str\n    vendor_name: str\n    issue_date: str\n    line_items: List[LineItem]\n    subtotal: float\n    tax_amount: float\n    total_due: float\n\n# In production: Pass image bytes + schema to Gemini 2.0 Flash or Florence-2\nsample_extracted = InvoiceData(\n    invoice_number="INV-2026-0042",\n    vendor_name="Systems Limited Lahore",\n    issue_date="2026-10-15",\n    line_items=[\n        LineItem(description="Cloud GPU Hosting T4", quantity=10, unit_price=1200.0, total_price=12000.0),\n        LineItem(description="LLM Inference Setup", quantity=1, unit_price=25000.0, total_price=25000.0)\n    ],\n    subtotal=37000.0,\n    tax_amount=5920.0,\n    total_due=42920.0\n)\n\nprint(sample_extracted.model_dump_json(indent=2))', 'diagram_script': '@preset midnight\n@animate flow\nflow LR: Document Visual Intelligence Pipeline\n  pdf[Scanned PDF / Receipt Image] $browser -> vlm[Visual Document Model Florence-2 / Gemini] $cpu\n  vlm -> visual_layout[Spatial Layout & Table Understanding] $layers\n  visual_layout -> schema[Pydantic JSON Validation Engine] $lock *\n  schema -> clean_json[Structured Validated Invoice JSON] $server', 'diagram_type': 'flow', 'resources': [{'title': 'Donut: Document Understanding Transformer', 'url': 'https://arxiv.org/abs/2111.15664'}, {'title': 'Microsoft Florence-2 Vision Foundation Model', 'url': 'https://huggingface.co/microsoft/Florence-2-large'}], 'xp_reward': 25, 'order_index': 3}, {'lesson_code': '12.4', 'slug': 'whisper-speech-audio-llms', 'title': 'Audio & Speech Processing: OpenAI Whisper & Audio-LLM Integrations', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, audio speech processing mein raw waveform (16,000 samples per second) ko direct neural network mein feed karna bohot inefficient hota hai.\n\nOpenAI ka **Whisper** standard audio pipeline follow karta hai:\n1. **Log-Mel Spectrogram**: Audio ko 25-millisecond windows (with 10ms hop length) mein divide karke Fourier Transform (FFT) apply kiya jata hai, aur frequencies ko human ear ki sensitivity (Mel scale, 80 ya 128 channels) par map kiya jata hai.\n2. **Audio Encoder**: 2D Mel-spectrogram ko convolutional layers aur Transformer blocks se process karke acoustic representations banata hai.\n3. **Autoregressive Text Decoder**: Multi-lingual text tokens predict karta hai with timestamp tokens (`<|0.00|>`, `<|2.40|>`) jo word-level alignments provide karte hain.\n\nWhisper Roman Urdu aur Pakistani accents par bohot shandaar kaam karta hai jab aap initial prompt parameter mein thora context pass karein!', 'english_summary': 'Understand speech-to-text processing using OpenAI Whisper, Log-Mel spectrogram feature extraction, and timestamp alignment tokens for audio-LLM architectures.', 'code_example': 'import numpy as np\n\ndef compute_mock_mel_spectrogram(audio_signal: np.ndarray, num_mel_bins: int = 80) -> np.ndarray:\n    """Conceptual representation of transforming 1D audio waveform into 2D Mel Spectrogram."""\n    # Window framing: 25ms window, 10ms hop\n    hop_length = 160 # 10ms at 16kHz\n    num_frames = len(audio_signal) // hop_length\n    \n    # 2D feature matrix: [Frequency Channels, Time Frames]\n    mel_spectrogram = np.random.randn(num_mel_bins, num_frames)\n    return mel_spectrogram\n\n# 2 seconds of 16kHz audio waveform\naudio = np.random.randn(32000)\nmel = compute_mock_mel_spectrogram(audio)\n\nprint(f"Input Raw Audio Samples: {len(audio):,}")\nprint(f"Generated Mel-Spectrogram shape: {mel.shape} (80 mel bins x {mel.shape[1]} time frames)")', 'diagram_script': '@preset midnight\n@animate flow\nflow LR: Whisper Speech Processing Flow\n  raw_wav[1D Audio Waveform 16kHz] $terminal -> stft[Short-Time Fourier Transform FFT] $cpu\n  stft -> mel[80-Channel Log-Mel Spectrogram] $layers\n  mel -> enc[Whisper Audio Encoder ViT] $server *\n  enc -> dec[Autoregressive Decoder + Timestamp Tokens] $brain\n  dec -> urdu_txt[Transcribed Roman Urdu Text with Timestamps] $terminal', 'diagram_type': 'flow', 'resources': [{'title': 'OpenAI Whisper Paper', 'url': 'https://arxiv.org/abs/2212.04356'}, {'title': 'Hugging Face Whisper Fine-Tuning Guide', 'url': 'https://huggingface.co/blog/fine-tune-whisper'}], 'xp_reward': 25, 'order_index': 4}, {'lesson_code': '12.5', 'slug': 'video-understanding-temporal-attention', 'title': 'Video AI & Temporal Understanding: Keyframe Sampling & Dynamic Attention', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, video dar-asal static images ka sequence hota hai jo waqt (time dimension) ke sath badalta hai. Agar ek 10 minute ki video 30 frames per second (fps) par ho, to total 18,000 frames bante hain! Agar har frame ko VLM mein bhejenge to context window explode ho jayegi aur hazaron dollars burn honge.\n\nModern Video AI do intelligent sampling strategies use karti hai:\n1. **Scene Change & Keyframe Extraction**: OpenCV ya ffmpeg ke zariye sirf wo frames extract kiye jate hain jahan camera angle ya screen content badalta hai (Color Histogram Differences / Optical Flow thresholding). Aam tor par 1 fps ya 0.5 fps sample rate 95% information retain karti hai.\n2. **Temporal Attention**: Video tokens ko 3D grid $(T, H, W)$ mein treat kiya jata hai. Model spatial attention (frame ke andar cheezein) aur temporal attention (frame $t_1$ se $t_2$ ke darmiyan action ka sequence) ko aapas mein correlate karta hai.\n\nIs technique se aap 1-hour lambi lecture videos ya CCTV footage ko digest karke exact second par event dhoond sakte hain!', 'english_summary': 'Process long-form video intelligence using OpenCV keyframe sampling, scene detection, and temporal cross-attention to analyze events across time.', 'code_example': 'import cv2\nimport numpy as np\n\ndef extract_uniform_keyframes(video_path: str, max_frames: int = 8) -> list:\n    """Extracts uniformly spaced keyframes from a video file for VLM processing."""\n    # Mocking video frame extraction logic\n    total_frames = 1800 # 60 seconds at 30fps\n    frame_indices = np.linspace(0, total_frames - 1, max_frames, dtype=int)\n    \n    extracted_frames = []\n    for idx in frame_indices:\n        timestamp_sec = idx / 30.0\n        # In production: cap.set(cv2.CAP_PROP_POS_FRAMES, idx); ret, frame = cap.read()\n        extracted_frames.append({"frame_idx": int(idx), "timestamp_sec": round(timestamp_sec, 2)})\n        \n    return extracted_frames\n\nframes = extract_uniform_keyframes("lecture_ai_ustaad.mp4", max_frames=6)\nfor f in frames:\n    print(f"Extracted Frame at {f[\'timestamp_sec\']}s (Index: {f[\'frame_idx\']})")', 'diagram_script': '@preset midnight\n@animate flow\nflow LR: Video Temporal Sampling Pipeline\n  video[Raw Video Stream 30 FPS] $browser -> sampler[Uniform / Scene-Change Sampler] $cpu\n  sampler -> frames[Keyframes: 1 FPS (e.g. 10 frames)] $layers\n  frames -> temporal_attn[Temporal & Spatial Cross-Attention] $brain *\n  temporal_attn -> qa_engine[Timestamp-Grounded Video Q&A] $server', 'diagram_type': 'flow', 'resources': [{'title': 'Google VideoPrism Foundation Model', 'url': 'https://arxiv.org/abs/2402.13217'}, {'title': 'OpenCV Video Processing in Python', 'url': 'https://docs.opencv.org/4.x/dd/d43/tutorial_py_video_display.html'}], 'xp_reward': 25, 'order_index': 5}, {'lesson_code': '12.6', 'slug': 'capstone-multimodal-intelligence-engine', 'title': 'Module 12 Capstone: Multimodal Document & Video Intelligence Engine', 'duration_minutes': 50, 'lesson_type': 'project', 'roman_urdu_content': 'So guys, congratulations! Aap Module 12 ke Capstone project par pohanch chuke hain. Is capstone mein aap ek unified **Multimodal Intelligence Engine** develop karenge jo text, complex visual documents (diagrams/tables), aur audio recordings teeno ko ek sath ingest aur analyze karega!\n\nAapka Capstone Architecture:\n1. **Visual Document Parser**: Complex technical PDF reports se tables aur flowcharts visually crop karke multimodal embeddings generate karega.\n2. **Audio Transcription Layer**: Voice queries ya meeting recordings ko Whisper ke zariye timestamped text mein convert karega.\n3. **Cross-Modal Retrieval**: User text ya image prompt bhej sakta hai ("Find me the quarterly revenue chart in this 50-page PDF") aur engine exact visual page crop return karega.\n4. **Structured JSON Synthesizer**: Final answer visual grounding (bounding box coordinates) aur verified citations ke sath return karega.\n5. **Interactive UI**: Svelte 5 ya Streamlit interface jahan user PDF upload kare, audio record kare, aur live streaming answers visual highlights ke sath dekhe!', 'english_summary': 'Assemble the Module 12 Capstone: a production Multimodal Document and Video Intelligence Engine combining visual table extraction, Whisper audio transcription, and cross-modal retrieval.', 'code_example': '# Capstone Multimodal Engine Integration Pipeline\nfrom typing import Dict, Any\n\nclass MultimodalIntelligenceEngine:\n    def __init__(self):\n        print("Multimodal Engine initialized: Vision + Audio + LLM active.")\n        \n    def process_query(self, text_query: str, visual_asset: str = None, audio_asset: str = None) -> Dict[str, Any]:\n        result = {\n            "query": text_query,\n            "modalities_analyzed": ["text"],\n            "findings": []\n        }\n        \n        if visual_asset:\n            result["modalities_analyzed"].append("vision")\n            result["findings"].append({\n                "type": "chart_analysis",\n                "extracted_data": {"Q3_Growth": "+24%", "Total_Users": "1.2M"},\n                "confidence": 0.96\n            })\n            \n        if audio_asset:\n            result["modalities_analyzed"].append("audio")\n            result["findings"].append({\n                "type": "audio_transcript",\n                "speaker": "Mentor",\n                "snippet": "AI Ustaad production curriculum graduation complete."\n            })\n            \n        return result\n\nengine = MultimodalIntelligenceEngine()\noutput = engine.process_query(\n    text_query="Summarize financial chart and verified voice note.",\n    visual_asset="balance_sheet.png",\n    audio_asset="meeting_note.wav"\n)\nprint("Multimodal Engine Output:", output)', 'diagram_script': '@preset midnight\n@animate pulse\narch LR: Capstone Multimodal Engine Architecture\n  user_inputs[Text + Image PDF + Audio WAV] $browser -> ingest[Multi-Modal Ingestion Gateway] $server\n  ingest -> doc_vlm[Visual Document Parser] $layers\n  ingest -> audio_whisper[Whisper Speech Engine] $cpu\n  doc_vlm & audio_whisper -> fusion[Cross-Modal Context Fusion] $database *\n  fusion -> vlm_core[Multimodal Foundation LLM] $brain\n  vlm_core -> grounded_out[Visual Grounded Response + Bounding Boxes] $terminal', 'diagram_type': 'arch', 'resources': [{'title': 'Gemini Multimodal Ingestion Docs', 'url': 'https://ai.google.dev/gemini-api/docs/multimodal'}, {'title': 'Multimodal Retrieval Augmented Generation (M-RAG)', 'url': 'https://arxiv.org/abs/2410.08182'}], 'xp_reward': 50, 'order_index': 6}], 'practice_checkpoint': {'title': 'Handwritten Doctor Prescription & Urdu Audio Transcriber', 'urdu_title': 'Doctor Prescription OCR & Audio Transcriber', 'description': 'Doctor ki tehrir (handwritten bad handwriting) aur tez bolay gaye Urdu audio notes ko Whisper Large v3 + Vision LLM se parse karke structured medicine dosage JSON generate karein.', 'colab_url': 'https://colab.research.google.com/drive/1ai_ustaad_mod12_doctor_ocr', 'checklist': ['Whisper audio chunking & transcription', 'Vision LLM multimodal prompt with dosage schema', 'Pydantic JSON schema strict enforcement', 'Medicine interaction warning system'], 'xp_reward': 350, 'badge_name': 'hakeem-ai'}}, {'phase_slug': 'phase-5-specialization-capstone', 'module_number': 13, 'slug': 'local-ai-and-edge-devices', 'real_world_deliverable': '100% Offline Autonomous Edge AI Assistant with Voice & Local RAG', 'zero_gpu_recipe': {'platform': 'Local Consumer Laptop (Mac M-series / Intel / AMD) / Raspberry Pi', 'vram_required': '0 GB GPU (Runs 100% on CPU RAM with AVX-512 / Metal)', 'estimated_cost': '$0.00 Free', 'compute_units_tip': 'llama.cpp and Ollama run 3B and 8B quantized GGUF models directly on standard consumer CPU RAM with zero cloud dependency.', 'one_click_command': 'ollama run llama3.2:3b'}, 'title': 'Module 13: Local AI & Edge Devices', 'weeks_range': 'Weeks 18-19', 'estimated_hours': 14, 'learning_outcomes': ['C++ Inference optimization: llama.cpp architecture, GGUF binary quantization formats aur CPU vectorization', 'Ollama deep dive: Custom Modelfiles, system prompt templating, REST API automation aur memory swapping', 'Hardware acceleration: Apple Silicon Metal Performance Shaders (MPS), Vulkan cross-platform aur AMD ROCm', 'In-browser AI execution: WebGPU, Wasm (WebAssembly) aur Transformers.js for zero-server latency', 'Embedded Edge AI: Nvidia Jetson Orin Nano, Raspberry Pi 5 NPU aur INT4 embedded model deployment', '100% privacy-preserving offline AI architectures for confidential healthcare, legal aur field operations'], 'practical_tasks': ['llama.cpp build karein local machine par with native AVX-512 / Metal flags', 'Custom Ollama Modelfile create karein Roman Urdu personality aur parameter constraints ke sath', 'In-browser sentiment classifier aur chat client deploy karein using WebGPU & Transformers.js', 'Raspberry Pi / Jetson benchmark run karein measuring tokens per second and thermal throttling', 'Complete offline RAG pipeline build karein using local ChromaDB and Ollama embeddings'], 'resources': [{'title': 'llama.cpp GitHub Repository', 'url': 'https://github.com/ggerganov/llama.cpp'}, {'title': 'Ollama Documentation & Modelfiles', 'url': 'https://github.com/ollama/ollama/blob/main/docs/modelfile.md'}, {'title': 'Transformers.js In-Browser AI', 'url': 'https://huggingface.co/docs/transformers.js/index'}, {'title': 'WebGPU W3C Specification', 'url': 'https://www.w3.org/TR/webgpu/'}], 'diagram_script': '@preset midnight\n@animate flow\nflow LR: Module 13 Local AI Execution Stack\n  hardware[Consumer CPU / Apple M-Chip / NPU] $cpu -> backend[llama.cpp / Vulkan / Metal] $layers\n  backend -> gguf[Quantized GGUF Q4_K_M Weights] $database\n  backend -> ollama[Ollama Local REST Daemon] $server *\n  ollama -> app[Private Offline Application] $browser', 'diagram_preset': 'midnight', 'diagram_animation': 'flow', 'badge_slug': 'production-ready', 'order_index': 13, 'lessons': [{'lesson_code': '13.1', 'slug': 'llama-cpp-gguf-cpu-optimization', 'title': 'Running AI Locally: llama.cpp, GGUF Formats & CPU Optimization', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, agar aapke pas koi mehnga Nvidia GPU nahi hai, sirf ek normal 16GB RAM wala laptop hai, to kya aap Llama 3 ya DeepSeek run kar sakte hain? **100% YES!**\n\nGeorgi Gerganov ka **llama.cpp** software engineering ki dunya ka masterclass project hai! Yeh pure C/C++ mein likha gaya hai with zero external dependencies.\nIske ahem features:\n1. **GGUF (GPT-Generated Unified Format)**:\n   Model ke tamam tensors, metadata, tokenizer vocabulary, aur hyper-parameters ek single binary file mein store hote hain. GGUF memory-mapped (`mmap`) hota hai, yaani file load hote hi instant execute hona shuru ho jati hai bina poori RAM occupy kiye!\n2. **K-Quants (Q4_K_M, Q5_K_M)**:\n   Uniform quantization ki bajaye different tensor layers ko different bit-widths assign karta hai (critical attention layers ko 5-bit ya 6-bit aur baqi weights ko 4-bit) taake minimal RAM mein maximum intelligence mile.\n3. **SIMD CPU Vectorization**:\n   Modern Intel/AMD CPUs ke AVX2, AVX-512, aur ARM NEON instructions ko direct assembly level par target karta hai, jis se CPU par 15 se 30 tokens/second ki smooth speed milti hai!', 'english_summary': "Understand Georgi Gerganov's llama.cpp C/C++ architecture, the unified GGUF binary format, mmap memory management, and AVX-512/ARM NEON vectorization.", 'code_example': '# Compiling and Running llama.cpp with Hardware Acceleration\n# On Linux / Windows (MSVC or MinGW) with AVX2:\n# cmake -B build -DGGML_AVX2=ON && cmake --build build --config Release\n\n# Running Quantized Llama 3.2 3B locally on CPU:\n# ./build/bin/llama-cli \\\n#     -m ./models/Llama-3.2-3B-Instruct-Q4_K_M.gguf \\\n#     -p "Salam! AI Ustaad par local inference kaise fast hota hai?" \\\n#     -n 256 \\\n#     --threads 8 \\\n#     --temp 0.7\n\nprint("llama.cpp CLI configuration verified for low-latency CPU execution!")', 'diagram_script': '@preset midnight\n@animate flow\nflow LR: llama.cpp Architecture & Memory Mapping\n  gguf_file[GGUF Binary File on Disk] $database -> mmap[OS mmap Zero-Copy Virtual Memory] $server\n  mmap -> cpu_cores[Multi-Core CPU Threads with AVX-512] $cpu *\n  cpu_cores -> simd[SIMD Vectorized Dot Product Kernels] $layers\n  simd -> token_stream[Instant Token Stream Output] $terminal', 'diagram_type': 'flow', 'resources': [{'title': 'llama.cpp GitHub Repository', 'url': 'https://github.com/ggerganov/llama.cpp'}, {'title': 'GGUF File Format Specification', 'url': 'https://github.com/ggerganov/ggml/blob/master/docs/gguf.md'}], 'xp_reward': 25, 'order_index': 1}, {'lesson_code': '13.2', 'slug': 'ollama-modelfiles-rest-orchestration', 'title': 'Ollama Deep Dive: Custom Modelfiles, Swapping & REST APIs', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, jabke llama.cpp raw engine hai, **Ollama** ne local AI ko Docker ki tarah aasan aur elegant bana diya hai!\n\nOllama background mein ek lightweight daemon run karta hai jo localhost port 11434 par OpenAI-compatible REST API expose karta hai.\nAhem capabilities:\n1. **The Modelfile**:\n   Dockerfiles ki tarah aap custom `Modelfile` likh sakte hain:\n   ```dockerfile\n   FROM llama3.2:3b\n   PARAMETER temperature 0.2\n   PARAMETER stop "<|eot_id|>"\n   SYSTEM """Aap AI Ustaad ke strict enterprise mentor hain."""\n   ```\n2. **Dynamic Model Swapping**:\n   Ollama automatically models ko VRAM/RAM mein swap in aur swap out karta hai. Jab request aati hai to model load hota hai, aur 5 minute idle rehne par memory release ho jati hai.\n3. **Local Embedding API**:\n   `/api/embeddings` endpoint se aap bina kisi third-party cost ke local text vectors generate kar sakte hain.', 'english_summary': 'Configure and automate local LLM workflows with Ollama, author custom Modelfiles with system templates, and orchestrate REST API inference.', 'code_example': 'import requests\nimport json\n\ndef query_local_ollama(prompt: str, model: str = "llama3.2:3b") -> str:\n    """Calls local Ollama daemon streaming REST endpoint on localhost:11434."""\n    url = "http://localhost:11434/api/generate"\n    payload = {\n        "model": model,\n        "prompt": prompt,\n        "stream": False,\n        "options": {\n            "temperature": 0.3,\n            "num_predict": 128\n        }\n    }\n    \n    try:\n        response = requests.post(url, json=payload, timeout=30)\n        data = response.json()\n        return data.get("response", "")\n    except requests.exceptions.ConnectionError:\n        return "Ollama daemon not running. Start with \'ollama serve\'."\n\n# Example execution\nanswer = query_local_ollama("AI Ustaad ka vision kya hai?")\nprint("Ollama Response:", answer)', 'diagram_script': '@preset midnight\n@animate flow\nflow LR: Ollama Local Daemon Architecture\n  client[Desktop / Web App] $browser -> rest[HTTP REST API localhost:11434] $network\n  rest -> daemon[Ollama Background Daemon] $server *\n  daemon -> modelfile[Modelfile Config & Template] $code\n  daemon -> engine[Embedded llama.cpp Runner] $cpu\n  engine -> weights[Cached GGUF Weights in ~/.ollama] $database', 'diagram_type': 'flow', 'resources': [{'title': 'Ollama Official Documentation', 'url': 'https://ollama.com/'}, {'title': 'Ollama API Specification', 'url': 'https://github.com/ollama/ollama/blob/main/docs/api.md'}], 'xp_reward': 25, 'order_index': 2}, {'lesson_code': '13.3', 'slug': 'hardware-acceleration-metal-vulkan', 'title': 'Edge Hardware Acceleration: Apple Metal (MPS), Vulkan & ROCm', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, local inference ko CPU se 10x tez karne ke liye humein edge hardware accelerators (Integrated GPUs aur NPUs) ka faida uthana parta hai.\n\nTeen primary acceleration backends industry standard hain:\n1. **Apple Silicon Metal (MPS)**:\n   M1, M2, M3, M4 chips par **Unified Memory Architecture (UMA)** hoti hai! CPU aur GPU ek hi high-bandwidth memory pool (100 GB/s se 800 GB/s) share karte hain. Koi PCIe transfer latency nahi hoti! Metal Performance Shaders use karke 70B parameter models Mac Studio par smoothly run hote hain.\n2. **Vulkan Cross-Platform**:\n   Vulkan ek low-level, high-performance graphics & compute API hai jo har platform (Windows, Linux, Android, Intel iGPU, AMD APU) par GPU compute enable karti hai bina proprietary CUDA drivers ke.\n3. **AMD ROCm**:\n   AMD Radeon graphics cards par open-source PyTorch aur vLLM execution enable karta hai.', 'english_summary': 'Leverage native hardware acceleration frameworks including Apple Metal Performance Shaders (MPS), cross-platform Vulkan compute, and AMD ROCm for local inference.', 'code_example': 'import torch\n\ndef detect_local_accelerator() -> str:\n    """Detects and returns optimal hardware acceleration device for PyTorch inference."""\n    if torch.cuda.is_available():\n        device_name = torch.cuda.get_device_name(0)\n        return f"CUDA Acceleration Active: {device_name}"\n    elif hasattr(torch.backends, "mps") and torch.backends.mps.is_available():\n        return "Apple Metal Performance Shaders (MPS) Unified Memory Active"\n    else:\n        num_threads = torch.get_num_threads()\n        return f"CPU AVX Vectorized Fallback ({num_threads} threads active)"\n\nstatus = detect_local_accelerator()\nprint("Local Hardware Diagnostic:", status)', 'diagram_script': '@preset midnight\n@animate pulse\narch LR: Hardware Acceleration Tiers\n  app[Inference Engine] $server -> dispatch[Hardware Dispatcher] $layers\n  dispatch -- Apple Silicon --> mps[Apple Metal Unified RAM] $cpu *\n  dispatch -- Nvidia Hardware --> cuda[CUDA Tensor Cores] $gpu\n  dispatch -- AMD / Intel iGPU --> vulkan[Vulkan Compute Pipeline] $chip\n  dispatch -- Fallback --> avx[Multi-Core CPU AVX-512] $database', 'diagram_type': 'arch', 'resources': [{'title': 'Apple Metal Performance Shaders Docs', 'url': 'https://developer.apple.com/metal/'}, {'title': 'Vulkan Compute Documentation', 'url': 'https://www.vulkan.org/'}], 'xp_reward': 25, 'order_index': 3}, {'lesson_code': '13.4', 'slug': 'in-browser-ai-webgpu', 'title': 'In-Browser Client AI: WebGPU & Transformers.js', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, socho agar aap ek aisi AI web application banayein jisme aapko backend server ka **ek rupiya bhi na dena pare**, aur user ka data user ke browser se **ek inch bhi bahar na jaye**!\n\nYeh futuristic architecture ab **WebGPU** aur **Transformers.js (v3)** ke sath 100% possible hai!\nWebGPU browser ka modern low-level graphics aur compute standard hai jo WebGL ke muqable mein direct GPU compute shaders execute karta hai.\nIska mechanism:\n1. Browser user ke local GPU (Intel, Nvidia, ya Apple M-chip) se direct WebAssembly (Wasm) aur WebGPU interface establish karta hai.\n2. ONNX Runtime Web model weights (jaise Phi-3.5-mini, Whisper, ya BGE-embeddings) ko user ke browser cache (IndexedDB) mein download aur cache karta hai.\n3. Generation, embedding retrieval, aur sentiment classification poori tarah client-side JavaScript mein execute hoti hai!\n\nZero server costs, zero API rate limits, aur 100% airtight data privacy!', 'english_summary': 'Run deep learning transformers directly inside client web browsers using WebGPU, ONNX Runtime Web, and Transformers.js with zero server infrastructure costs.', 'code_example': '// In-Browser AI with Transformers.js and WebGPU (Client-side JavaScript)\n// <script type="module">\n// import { pipeline } from \'https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.0.0\';\n\nasync function initBrowserAI() {\n    console.log("Initializing in-browser text classification on WebGPU...");\n    \n    // In production web client:\n    // const classifier = await pipeline(\'sentiment-analysis\', \'Xenova/distilbert-base-uncased-finetuned-sst-2-english\', {\n    //     device: \'webgpu\'\n    // });\n    // const output = await classifier(\'AI Ustaad makes local edge AI incredibly practical!\');\n    // console.log("WebGPU Result:", output);\n    \n    return { status: "WebGPU pipeline ready", device: "client-side GPU" };\n}\n\ninitBrowserAI().then(console.log);', 'diagram_script': '@preset midnight\n@animate flow\nflow LR: In-Browser WebGPU Execution Flow\n  browser[User Browser Tab] $browser -> idb[IndexedDB Cached ONNX Weights] $database\n  browser -> webgpu[WebGPU Compute Shader API] $cpu *\n  webgpu -> gpu[Local Client GPU Hardware] $chip\n  gpu -> dom[Direct DOM UI Update: Zero Network Latency] $terminal', 'diagram_type': 'flow', 'resources': [{'title': 'Transformers.js Documentation', 'url': 'https://huggingface.co/docs/transformers.js/index'}, {'title': 'WebGPU Fundamentals', 'url': 'https://webgpufundamentals.org/'}], 'xp_reward': 25, 'order_index': 4}, {'lesson_code': '13.5', 'slug': 'edge-ai-jetson-raspberry-pi', 'title': 'Edge AI on Embedded Hardware: Nvidia Jetson & Raspberry Pi NPUs', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, jab hum AI ko internet se door kisi factory floor, drone, smart camera, ya agricultural farm mein deploy karte hain jahan 4G/WiFi ka nam-o-nishan nahi hota, to humein **Embedded Edge AI** hardware chahiye hota hai.\n\nDo leading embedded computing platforms:\n1. **Nvidia Jetson Orin Nano (40-67 TOPS AI Performance)**:\n   Jetson ek credit-card size computer hai jisme 1024-core Nvidia Ampere GPU aur Tensor Cores mojood hote hain. Yeh 7-15 Watts power consume karta hai aur 4-bit quantized 7B models ko real-time 20+ tokens/sec par run kar sakta hai!\n2. **Raspberry Pi 5 + Raspberry Pi AI Kit (Hailo-8L NPU)**:\n   13 TOPS ka dedicated Neural Processing Unit (NPU) jo vision models (YOLOv8, Pose Estimation) ko sirf 2-3 Watts power par 30+ FPS video streams par execute karta hai!\n\nKey challenge: **Thermal Management & Power Throttling**. Edge devices par fan profiles, dynamic voltage scaling, aur model batch size ko tune karna lazmi hota hai taake chip overheat ho kar restart na ho.', 'english_summary': 'Deploy compact quantized models on embedded hardware such as Nvidia Jetson Orin and Raspberry Pi 5 NPUs with strict power, memory, and thermal constraints.', 'code_example': '# Monitoring Embedded Jetson Thermals & NPU Power (Python Edge Daemon)\nimport subprocess\nimport time\n\ndef read_jetson_telemetry() -> dict:\n    """Reads Tegrastats or thermal zone on Nvidia Jetson embedded device."""\n    try:\n        with open("/sys/devices/virtual/thermal/thermal_zone0/temp", "r") as f:\n            temp_milli = int(f.read().strip())\n            celsius = temp_milli / 1000.0\n    except FileNotFoundError:\n        celsius = 45.2 # Simulated baseline temperature\n        \n    return {\n        "cpu_temp_celsius": celsius,\n        "is_throttled": celsius > 80.0,\n        "power_mode": "15W_6CORE_BALANCED"\n    }\n\ntelemetry = read_jetson_telemetry()\nprint(f"Edge Device Temperature: {telemetry[\'cpu_temp_celsius\']} C | Throttled: {telemetry[\'is_throttled\']}")', 'diagram_script': '@preset midnight\n@animate flow\nflow LR: Embedded Edge AI Pipeline\n  sensor[CCTV Camera / Microphone Sensor] $browser -> npu[Hailo-8L NPU / Jetson Orin Tensor Cores] $chip *\n  npu -> int4_engine[Quantized INT4 Inference 10W Power] $cpu\n  int4_engine -> action[Local GPIO Relay Trigger / Alert] $server\n  int4_engine -> log[Local SQLite Storage: 100% Offline] $database', 'diagram_type': 'flow', 'resources': [{'title': 'Nvidia Jetson Orin Developer Documentation', 'url': 'https://developer.nvidia.com/embedded/jetson-orin'}, {'title': 'Raspberry Pi AI Kit Overview', 'url': 'https://www.raspberrypi.com/documentation/accessories/ai-kit.html'}], 'xp_reward': 25, 'order_index': 5}, {'lesson_code': '13.6', 'slug': 'capstone-offline-edge-assistant', 'title': 'Module 13 Capstone: 100% Offline Autonomous Edge AI Assistant', 'duration_minutes': 50, 'lesson_type': 'project', 'roman_urdu_content': 'So guys, congratulations! Aap Module 13 ke Capstone project par pohanch chuke hain. Is capstone mein aap ek mukammal **100% Offline Autonomous Edge AI Assistant** build karenge jo airplane mode par bhi voice commands sunega, local documents search karega, aur Roman Urdu mein jawab dega!\n\nAapka Capstone Architecture:\n1. **Local Speech-to-Text**: Whisper.cpp ya faster-whisper local CPU par audio stream ko text mein convert karega.\n2. **Local Vector Knowledge Base**: ChromaDB ya SQLite-vec local disk par chalegi with sentence-transformers embeddings (all-MiniLM-L6-v2 ya BGE-small).\n3. **Local LLM Engine**: Ollama ya llama.cpp ke zariye Llama 3.2 3B (Q4_K_M) local RAM par execute hoga.\n4. **Local Text-to-Speech (TTS)**: Piper TTS ya Kokoro local audio synthesizer ke zariye instant voice playback provide karega.\n5. **Zero-Network Audit**: Wireshark ya network disconnect karke prove karein ke system bina internet ke 100% functional rehta hai!', 'english_summary': 'Architect and deploy the Module 13 Capstone: a 100% offline, privacy-first Edge AI Assistant combining whisper.cpp speech recognition, local SQLite-vec RAG, and quantized Ollama inference.', 'code_example': '# Capstone Offline Assistant Coordinator\nclass OfflineEdgeAssistant:\n    def __init__(self):\n        self.device = "Local CPU / Edge Accelerator"\n        print("Offline Assistant online: Network connectivity = 0 (Airtight Privacy)")\n        \n    def execute_voice_turn(self, audio_input_bytes: bytes) -> dict:\n        # 1. Local STT (Whisper.cpp)\n        transcribed_text = "AI Ustaad platform ke offline safety protocols kya hain?"\n        \n        # 2. Local Vector Search (SQLite-vec)\n        retrieved_snippet = "Offline protocols require zero cloud telemetry and local disk encryption."\n        \n        # 3. Local LLM Reasoning (llama.cpp)\n        answer = "So guys, offline safety protocols ke teht tamam embeddings local SQLite file mein store hoti hain aur koi network packet bahar nahi jata."\n        \n        return {\n            "query": transcribed_text,\n            "context": retrieved_snippet,\n            "response": answer,\n            "offline_verified": True\n        }\n\nassistant = OfflineEdgeAssistant()\nresult = assistant.execute_voice_turn(b"mock_audio_bytes")\nprint("Offline Assistant Turn Result:", result)', 'diagram_script': '@preset midnight\n@animate pulse\narch LR: Capstone Offline Edge Assistant\n  mic[Local USB Microphone] $browser -> whisper_cpp[Local Whisper.cpp STT] $cpu\n  whisper_cpp -> query[Transcribed Query] $terminal\n  query -> local_rag[Local SQLite-vec Database] $database\n  query & local_rag -> llama_runner[llama.cpp / Ollama Engine] $server *\n  llama_runner -> piper_tts[Local Piper TTS Synthesizer] $chip\n  piper_tts -> speaker[Local Audio Speaker Output] $terminal', 'diagram_type': 'arch', 'resources': [{'title': 'Whisper.cpp High-Performance C++ Port', 'url': 'https://github.com/ggerganov/whisper.cpp'}, {'title': 'Piper Local Fast Neural TTS', 'url': 'https://github.com/rhasspy/piper'}], 'xp_reward': 50, 'order_index': 6}], 'practice_checkpoint': {'title': '100% Offline Exam Crammer Chatbot', 'urdu_title': 'Offline WebGPU Exam Crammer', 'description': 'Transformers.js + WebGPU ke zariye student ke browser mein Llama-3.2-1B-Instruct model 100% offline run karein taake bina internet / load-shedding ke exam revision ki ja sake.', 'colab_url': 'https://colab.research.google.com/drive/1ai_ustaad_mod13_offline_crammer', 'checklist': ['WebGPU device initialization in JavaScript', 'ONNX / Transformers.js quantized model loading', 'Zero-server edge inference loop', 'Local browser IndexedDB chat persistence'], 'xp_reward': 400, 'badge_name': 'bijli-proof'}}, {'phase_slug': 'phase-5-specialization-capstone', 'module_number': 14, 'slug': 'enterprise-capstone-and-career-launch', 'real_world_deliverable': 'Multi-Tenant Enterprise AI Platform with Auth, Billing, Observability & Live Defense', 'zero_gpu_recipe': {'platform': 'Fly.io / Render / Cloudflare Pages / Supabase Free Tier', 'vram_required': '0 GB (Cloud Serverless / Microservices Architecture)', 'estimated_cost': '$0.00 Free Tier', 'compute_units_tip': 'Deploy multi-tenant frontend on Cloudflare Pages, backend on Render, and Postgres/pgvector on Supabase completely within free tier limits.', 'one_click_command': 'docker compose up -d'}, 'title': 'Module 14: Enterprise Capstone & Career Launch', 'weeks_range': 'Weeks 19-20', 'estimated_hours': 20, 'learning_outcomes': ['Enterprise multi-tenant architecture: Row-Level Security (RLS), vector workspace isolation aur compliance audit trails', 'High availability & resilience engineering: Circuit breakers, exponential jitter backoff aur multi-cloud fallback', 'Monetization & cost governance: Token metering, user rate limits aur Stripe usage-based billing integration', 'Production packaging & release: Multi-stage Docker builds, Helm charts aur semantic versioning CI/CD pipelines', 'AI engineering career positioning: Technical architecture whitepapers, GitHub portfolio stardom aur live demos', 'Grand Capstone Defense: Live presentation, technical peer review aur graduation from the AI Ustaad curriculum'], 'practical_tasks': ['Supabase Postgres Row-Level Security policies configure karein multi-tenant vector partitioning ke liye', 'Stripe metered billing webhook listener implement karein tracking input and output tokens', 'Multi-stage Dockerfile optimize karein reducing production image size from 4GB to under 200MB', 'Interactive live portfolio project showcase deploy karein on Cloudflare Pages / Fly.io', 'Grand Capstone live defense conduct karein with comprehensive system architecture documentation'], 'resources': [{'title': 'Supabase Row Level Security Deep Dive', 'url': 'https://supabase.com/docs/guides/database/postgres/row-level-security'}, {'title': 'Stripe Usage-Based Metered Billing', 'url': 'https://stripe.com/docs/billing/subscriptions/usage-based'}, {'title': 'Docker Multi-Stage Builds Guide', 'url': 'https://docs.docker.com/build/building/multi-stage/'}, {'title': 'System Design for Enterprise AI Applications', 'url': 'https://github.com/donnemartin/system-design-primer'}], 'diagram_script': '@preset midnight\n@animate flow\nflow LR: Module 14 Enterprise Architecture\n  client[Cloudflare Pages Frontend] $browser -> gw[Multi-Tenant Gateway] $server *\n  gw -> rls[Supabase Postgres RLS & Vector Partition] $database\n  gw -> billing[Stripe Token Metering] $dollar\n  gw -> cluster[Resilient LLM Inference Cluster] $cpu\n  gw -> audit[Immutable Audit Log] $lock', 'diagram_preset': 'midnight', 'diagram_animation': 'flow', 'badge_slug': 'ai-graduate', 'order_index': 14, 'lessons': [{'lesson_code': '14.1', 'slug': 'enterprise-multi-tenant-architecture', 'title': 'Enterprise System Design: Multi-Tenant RLS, Vector Partitioning & Audit', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': "So guys, jab aap ek B2B SaaS AI product build karte hain jahan Company A (Bank) aur Company B (Hospital) dono aapka platform use kar rahe hain, to agar Company A ke user ko Company B ke confidential documents ka jawab ghalti se bhi mil gaya, to aapki company par millions dollars ka lawsuit ho sakta hai!\n\nEnterprise Multi-Tenancy ke teen pillars hote hain:\n1. **Row-Level Security (RLS)**:\n   Database level par har query par automatically `WHERE tenant_id = auth.jwt()->>'tenant_id'` enforce hota hai. Chahe backend application code mein developer `WHERE` clause bhool bhi jaye, database engine kisi doosre tenant ka data return hi nahi kar sakta!\n2. **Vector Space Partitioning**:\n   pgvector mein har vector index mein `metadata->>'tenant_id'` par HNSW / IVFFlat partial indexes banaye jate hain taake similarity search sirf tenant ke apne documents ke darmiyan execute ho.\n3. **Immutable Audit Trails**:\n   Har prompt, response, model version, aur data access event ko append-only audit table mein log kiya jata hai for SOC2 and ISO-27001 compliance.", 'english_summary': 'Architect airtight multi-tenant enterprise AI platforms utilizing Supabase Row-Level Security (RLS), partition-isolated vector indexes, and immutable audit logs.', 'code_example': "-- Enterprise Multi-Tenant RLS & pgvector Partitioning (PostgreSQL)\n-- 1. Enable RLS on vector documents table\nALTER TABLE public.document_embeddings ENABLE ROW LEVEL SECURITY;\n\n-- 2. Strict Tenant Isolation Policy based on JWT claims\nCREATE POLICY tenant_isolation_policy ON public.document_embeddings\n    FOR ALL\n    USING (tenant_id = (current_setting('request.jwt.claims', true)::jsonb ->> 'tenant_id')::uuid)\n    WITH CHECK (tenant_id = (current_setting('request.jwt.claims', true)::jsonb ->> 'tenant_id')::uuid);\n\n-- 3. Filtered HNSW Vector Index for blazing-fast isolated search\nCREATE INDEX idx_tenant_hnsw_vectors ON public.document_embeddings \nUSING hnsw (embedding vector_cosine_ops)\nWHERE is_active = true;", 'diagram_script': '@preset midnight\n@animate flow\nflow LR: Enterprise Multi-Tenant Isolation\n  req_a[Tenant A User (Bank)] $browser -> auth[JWT Auth & Tenant Context] $lock\n  req_b[Tenant B User (Hospital)] $browser -> auth\n  auth -> rls[Postgres Row-Level Security Engine] $server *\n  rls -- Partition A --> data_a[Tenant A Isolated Vectors] $database\n  rls -- Partition B --> data_b[Tenant B Isolated Vectors] $database', 'diagram_type': 'flow', 'resources': [{'title': 'PostgreSQL Row-Level Security Guide', 'url': 'https://www.postgresql.org/docs/current/ddl-rowsecurity.html'}, {'title': 'Multi-Tenancy in Vector Databases', 'url': 'https://supabase.com/docs/guides/ai'}], 'xp_reward': 25, 'order_index': 1}, {'lesson_code': '14.2', 'slug': 'high-availability-circuit-breakers', 'title': 'High Availability & Resilience: Circuit Breakers & Multi-Cloud Fallback', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, enterprise engineering ka qanoon hai: **"Everything fails, all the time."**\nOpenAI ka API down ho sakta hai, Anthropic par rate limit lag sakti hai, ya aapka primary cloud provider network outage face kar sakta hai. Agar aapki system in failures ko gracefully handle nahi karti to aapka 99.9% uptime SLA break ho jayega.\n\nIska solution **Circuit Breaker Pattern** aur **Multi-Cloud Dynamic Routing** hai:\n1. **Three Circuit States**:\n   - **CLOSED (Normal)**: Tamam requests primary model provider (jaise vLLM / OpenAI) ko jati hain.\n   - **OPEN (Tripped)**: Agar pichli 10 requests mein se 5 fail hon ya latency 3s se zyada ho, to circuit foran OPEN ho jata hai aur primary provider par requests bhejna band ho jata hai!\n   - **HALF-OPEN (Recovery)**: Kuch seconds baad circuit kuch probe requests primary ko bhej kar check karta hai; agar pass hon to CLOSED ho jata hai.\n2. **Exponential Jitter Backoff**:\n   Retry karte waqt uniform delay ki bajaye randomized exponential backoff (`delay = min(max_delay, base * 2^attempt) + random_jitter`) use kiya jata hai taake cascading "thundering herd" problem na bane.', 'english_summary': 'Implement enterprise reliability patterns including Circuit Breakers (Closed/Open/Half-Open), exponential jitter backoff, and automatic multi-cloud provider failover.', 'code_example': 'import time\nimport random\nfrom enum import Enum\n\nclass CircuitState(Enum):\n    CLOSED = "CLOSED"\n    OPEN = "OPEN"\n    HALF_OPEN = "HALF_OPEN"\n\nclass ResilientAIGateway:\n    def __init__(self, failure_threshold: int = 3, recovery_time_sec: float = 10.0):\n        self.state = CircuitState.CLOSED\n        self.failure_count = 0\n        self.failure_threshold = failure_threshold\n        self.recovery_time = recovery_time_sec\n        self.last_failure_time = 0\n        \n    def call_ai_service(self, prompt: str) -> str:\n        current_time = time.time()\n        \n        # Check if OPEN circuit can transition to HALF_OPEN\n        if self.state == CircuitState.OPEN:\n            if current_time - self.last_failure_time > self.recovery_time:\n                self.state = CircuitState.HALF_OPEN\n            else:\n                # Instant Failover to Secondary Provider (e.g. Groq / Cloudflare)\n                return f"[FAILOVER_PROVIDER] Handled via secondary provider: {prompt[:30]}..."\n                \n        try:\n            # Simulate primary call\n            return f"[PRIMARY_PROVIDER] Successful response: {prompt[:30]}..."\n        except Exception:\n            self.failure_count += 1\n            self.last_failure_time = current_time\n            if self.failure_count >= self.failure_threshold:\n                self.state = CircuitState.OPEN\n            return "[FAILOVER_PROVIDER] Handled via secondary provider fallback."\n\ngateway = ResilientAIGateway()\nprint("Circuit Breaker Gateway Status:", gateway.state.value)', 'diagram_script': '@preset midnight\n@animate flow\nflow LR: Circuit Breaker State Transition\n  closed[CLOSED: Normal Traffic] $server -- Failures > Threshold --> open_state[OPEN: Route to Fallover Provider] $shield\n  open_state -- Recovery Timeout --> half_open[HALF-OPEN: Test Canary Probe] $layers\n  half_open -- Canary Success --> closed *\n  half_open -- Canary Fails --> open_state', 'diagram_type': 'flow', 'resources': [{'title': 'Martin Fowler: Circuit Breaker Pattern', 'url': 'https://martinfowler.com/bliki/CircuitBreaker.html'}, {'title': 'AWS Architecture Center: Exponential Backoff And Jitter', 'url': 'https://aws.amazon.com/blogs/architecture/exponential-backoff-and-jitter/'}], 'xp_reward': 25, 'order_index': 2}, {'lesson_code': '14.3', 'slug': 'token-metering-stripe-billing', 'title': 'Monetization & Governance: Token Metering & Stripe Usage-Based Billing', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, agar aapka user bohot lambi videos ya 100-page ke documents summarize karwata hai aur aap us se fixed $10/month charge kar rahe hain, to aapki company kuch hi hafton mein bankrupt ho jayegi!\n\nModern AI companies ka business model **Usage-Based (Metered) Billing** hota hai:\n1. **Accurate Token Metering**:\n   Har API response ke baad input tokens aur output tokens ko extract karke Redis TimeSeries ya Postgres mein asynchronously log kiya jata hai.\n2. **Stripe Metering API Integration**:\n   Stripe ke **Billing Meters** feature ko har ghante customer ka aggregated token count report kiya jata hai (`stripe.billing.meter_events.create`).\n3. **Hard & Soft Quotas**:\n   Jab customer apne monthly budget (jaise $50) ke 80% par pohanchta hai to automated email notification trigger hoti hai (Soft Limit); 100% par non-critical requests block ho jati hain (Hard Limit) taake runaway bill shocks se bacha ja sake.', 'english_summary': 'Implement precise token metering pipelines and integrate Stripe Usage-Based Billing meters to monetize AI applications sustainably with budget quotas.', 'code_example': 'import stripe\nimport os\n\nstripe.api_key = os.getenv("STRIPE_SECRET_KEY", "sk_test_mock_key")\n\ndef report_token_usage_to_stripe(customer_id: str, input_tokens: int, output_tokens: int):\n    """Reports consumed AI tokens to Stripe Usage-Based Billing Meter."""\n    total_tokens = input_tokens + output_tokens\n    \n    # In production with live Stripe API:\n    # stripe.billing.MeterEvent.create(\n    #     event_name="ai_tokens_consumed",\n    #     payload={\n    #         "value": str(total_tokens),\n    #         "stripe_customer_id": customer_id\n    #     }\n    # )\n    \n    cost_estimate_usd = (input_tokens * 0.00000015) + (output_tokens * 0.0000006)\n    return {\n        "customer_id": customer_id,\n        "total_tokens": total_tokens,\n        "cost_estimate_usd": round(cost_estimate_usd, 6),\n        "status": "reported_to_stripe"\n    }\n\nusage = report_token_usage_to_stripe("cus_PK10294", input_tokens=1540, output_tokens=420)\nprint("Stripe Metering Event:", usage)', 'diagram_script': '@preset midnight\n@animate flow\nflow LR: Token Metering & Stripe Billing Architecture\n  gateway[AI Gateway Response] $server -> counter[Async Token Counter Worker] $cpu\n  counter -> db[PostgreSQL Token Ledger] $database\n  counter -> stripe[Stripe Billing Meter API] $dollar *\n  stripe -> invoice[Monthly Usage-Based End Customer Invoice] $chart', 'diagram_type': 'flow', 'resources': [{'title': 'Stripe Usage-Based Metered Billing Docs', 'url': 'https://stripe.com/docs/billing/subscriptions/usage-based'}, {'title': 'Managing LLM Costs & Quotas', 'url': 'https://www.datadoghq.com/blog/llm-cost-management/'}], 'xp_reward': 25, 'order_index': 3}, {'lesson_code': '14.4', 'slug': 'packaging-open-source-helm-docker', 'title': 'Packaging & Distribution: Multi-Stage Docker & Helm Charts', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, jab aapka AI system local machine par chal raha hota hai to "It works on my machine!" kehna kafi nahi hota. Production deployment ke liye containerization aur automated packaging lazmi hai.\n\n1. **Multi-Stage Docker Builds**:\n   PyTorch aur CUDA libraries bohot bari hoti hain (single image 6GB se 10GB ki ban jati hai!).\n   Multi-stage build mein pehla stage (Builder) dependencies compile karta hai, aur final stage (Runtime) sirf zaroori compiled artifacts copy karta hai. Nateeja? Container image size **70% chota** ho jata hai, attack surface reduce hoti hai, aur deploy speed 4x fast hoti hai!\n2. **Kubernetes Helm Charts**:\n   Poore platform (Frontend, Backend, Redis, Vector DB, KEDA Autoscaler) ko ek single configurable Helm chart package (`values.yaml`) mein define kiya jata hai taake enterprise client ek command `helm install ai-ustaad ./chart` se poora stack deploy kar sake!', 'english_summary': 'Package enterprise AI microservices with multi-stage Docker builds to slash container footprint and define declarative Kubernetes Helm charts for one-click deployment.', 'code_example': '# Multi-Stage Dockerfile for High-Performance AI Gateway\n# Stage 1: Build stage with compiler toolchain\nFROM rust:1.80-slim as builder\nWORKDIR /app\nCOPY Cargo.toml Cargo.lock ./\nCOPY src ./src\nRUN cargo build --release\n\n# Stage 2: Minimal Distroless / Debian Runtime\nFROM debian:bookworm-slim\nWORKDIR /app\nRUN apt-get update && apt-get install -y --no-install-recommends ca-certificates && rm -rf /var/lib/apt/lists/*\nCOPY --from=builder /app/target/release/ai_gateway /app/ai_gateway\n\nEXPOSE 8080\nUSER 1001\nCMD ["/app/ai_gateway"]', 'diagram_script': '@preset midnight\n@animate flow\nflow LR: Multi-Stage Docker Optimization\n  heavy[Stage 1: Heavy Build Environment 3.5GB (Compilers + SDKs)] $layers -> compile[Compile Binary] $cpu\n  compile -> light[Stage 2: Slim Runtime Environment 95MB (Zero Bloat)] $server *\n  light -> registry[Deploy to Docker Hub / Cloudflare] $cloud', 'diagram_type': 'flow', 'resources': [{'title': 'Docker Multi-Stage Builds Documentation', 'url': 'https://docs.docker.com/build/building/multi-stage/'}, {'title': 'Helm: The Kubernetes Package Manager', 'url': 'https://helm.sh/docs/'}], 'xp_reward': 25, 'order_index': 4}, {'lesson_code': '14.5', 'slug': 'ai-career-portfolio-stardom', 'title': 'AI Career Launch: Viral Demos, Technical Whitepapers & GitHub Stardom', 'duration_minutes': 35, 'lesson_type': 'theory_and_code', 'roman_urdu_content': 'So guys, aapne 20 hafton mein duniya ke sab se advanced AI concepts seekh liye hain. Lekin agar duniya ko aapke kaam ka pata hi nahi chalega to aapko top global AI companies (San Francisco, London, Dubai) se remote offers kaise milenge?\n\nAapko apna **Proof of Work** show karna hai:\n1. **The Viral 60-Second Video Demo**:\n   Log lambe text nahi parhte! Twitter (X) aur LinkedIn par apne Capstone ka ek 60-second crisp screen recording post karein jisme real-time token streaming, diagram visual grounding, aur speed demonstrate ho rahi ho.\n2. **The Architecture Whitepaper**:\n   Apne GitHub repo ke README mein clear DiagramKit architecture diagrams, benchmark graphs (Latency P99, Throughput comparison), aur design trade-offs document karein.\n3. **Open-Source Contribution Blueprint**:\n   Popular AI repos (vLLM, Unsloth, Langfuse, LiteLLM) mein bug fixes aur documentation PRs submit karein. Yeh GitHub profile ko global recruiters ki nazar mein golden bana deta hai!', 'english_summary': 'Position your AI Engineering profile globally with high-impact 60-second video demos, rigorous technical architecture READMEs, and open-source contributions.', 'code_example': '# GitHub Repository README Blueprint for Top AI Projects\n# # Enterprise Multimodal RAG with ColPali & vLLM\n# \n# [![License: MIT](https://img.shields.io/badge/License-MIT-yellow.svg)](https://opensource.org/licenses/MIT)\n# [![Docker Pulls](https://img.shields.io/badge/docker-ready-blue.svg)](https://hub.docker.com/)\n# \n# ## Architecture Overview\n# Built with Rust Axum, vLLM PagedAttention, and Supabase pgvector.\n# \n# ## Benchmarks\n# - **Throughput**: 450 tokens/sec on single Nvidia L4\n# - **P99 Latency**: 42ms TTFT (Time to First Token)\n# - **Test Coverage**: 94% with DeepEval CI gates\n# \n# ## Quickstart\n# ```bash\n# docker compose up -d\n# curl -N http://localhost:8080/v1/chat/stream -d \'{"prompt": "Hello"}\'\n# ```\n\nprint("README template validated for high-impact developer branding!")', 'diagram_script': '@preset midnight\n@animate flow\nflow LR: AI Engineering Career Funnel\n  repo[GitHub Open Source Repository] $code -> demo[60s X / LinkedIn Video Demo] $browser\n  demo -> whitepaper[Technical Architecture Whitepaper] $database\n  whitepaper -> interview[Global Remote Interview Offers ($100k-$180k)] $server *', 'diagram_type': 'flow', 'resources': [{'title': 'How to Build a World-Class Developer Portfolio', 'url': 'https://github.com/readme/guides'}, {'title': 'Open Source Contribution Guide', 'url': 'https://opensource.guide/how-to-contribute/'}], 'xp_reward': 25, 'order_index': 5}, {'lesson_code': '14.6', 'slug': 'grand-capstone-defense-graduation', 'title': 'Grand Capstone Defense: Enterprise AI Platform Graduation', 'duration_minutes': 60, 'lesson_type': 'project', 'roman_urdu_content': 'So guys, TAMAM AI USTAAD FELLOWS KO MUBARAK HO! Aap curriculum ke aakhri aur sab se azeem marhalay par pohanch chuke hain: **The Grand Capstone Defense & Graduation**!\n\nAapne Python aur tensors ki pehli line se le kar Transformers, Deep Learning, Modern Hybrid RAG, Autonomous Multi-Agent Swarms, LoRA fine-tuning, DeepSeek-R1 GRPO, vLLM PagedAttention, aur Multi-Tenant Cloud Architecture tak ka 20-hafton ka safar tay kiya hai.\n\nAapka Final Graduation Criteria:\n1. **Live Production Deployment**: Ek live public URL (jaise `https://your-capstone.pages.dev`) jahan platform active aur testable ho.\n2. **Complete Full-Stack Architecture**:\n   - Modern Svelte 5 / Next.js UI with real-time SSE token streaming.\n   - Rust Axum ya FastAPI resilient gateway with rate-limiting.\n   - Supabase Postgres with pgvector, Row-Level Security (RLS) aur audit logs.\n   - NeMo Guardrails aur Presidio safety filters.\n   - Distributed telemetry dashboard (Langfuse / Prometheus).\n3. **Defense Presentation**: 10-minute video presentation jisme aap architecture decisions, latency trade-offs, aur edge case handling explain karein.\n\nJab aap yeh defense submit karenge to aapko **Official AI Ustaad Graduate Badge ** aur Certificate of Engineering Mastery se nawaza jayega!', 'english_summary': 'Deliver your Grand Capstone Defense: demonstrate a live multi-tenant enterprise AI system with streaming UI, Rust gateway, RLS vector storage, and safety guardrails to graduate.', 'code_example': '# Final AI Ustaad Platform Graduation Verification Script\ndef verify_graduation_readiness(checklist: dict) -> bool:\n    print("AI USTAAD — ENGINEERING MASTERY GRADUATION AUDIT")\n    print("=" * 55)\n    all_passed = True\n    for requirement, status in checklist.items():\n        symbol = "✅" if status else "❌"\n        print(f"{symbol} {requirement}")\n        if not status:\n            all_passed = False\n            \n    print("=" * 55)\n    if all_passed:\n        print("CONGRATULATIONS! You have mastered the complete AI curriculum.")\n        print("Awarded: [AI Graduate Badge ] | Status: PRODUCTION READY")\n    else:\n        print("Please resolve missing items before final graduation defense.")\n    return all_passed\n\naudit = {\n    "Live Production Endpoint Deployed": True,\n    "Multi-Tenant RLS & Vector Partitioning": True,\n    "Real-Time SSE Streaming Gateway Active": True,\n    "Enterprise Safety Rails & PII Redaction": True,\n    "OpenTelemetry Distributed Tracing Configured": True,\n    "Automated CI/CD Evaluation Tests Passing": True\n}\n\nverify_graduation_readiness(audit)', 'diagram_script': '@preset midnight\n@animate pulse\narch LR: The Complete AI Ustaad Full-Stack Universe\n  learner[Zero: Eager Student] $terminal -> p1[Phase 1: Foundations] $code\n  p1 -> p2[Phase 2: Core ML & Deep Learning] $layers\n  p2 -> p3[Phase 3: Modern GenAI & RAG] $database\n  p3 -> p4[Phase 4: Fine-Tuning & MLOps] $cpu\n  p4 -> p5[Phase 5: Specialization & Enterprise] $server *\n  p5 -> hero[Hero: Production AI Engineer ] $cloud', 'diagram_type': 'arch', 'resources': [{'title': 'AI Ustaad Official Platform', 'url': 'https://ai-ustaad.pages.dev'}, {'title': 'Global AI Engineering Community', 'url': 'https://github.com'}], 'xp_reward': 100, 'order_index': 6}], 'practice_checkpoint': {'title': 'Global AI Micro-SaaS Capstone Defense', 'urdu_title': 'Commercial AI SaaS Capstone Launch', 'description': 'Supabase Auth, PostgreSQL RLS, Stripe billing aur Cloudflare Pages deployment ke sath ek commercial AI SaaS banayein aur live internet par launch karein!', 'colab_url': 'https://colab.research.google.com/drive/1ai_ustaad_mod14_capstone_defense', 'checklist': ['Multi-tenant Supabase schema with RLS', 'Stripe webhook payment integration', 'Production deployment on Cloudflare Pages', 'Live 60-second video demo & GitHub repository'], 'xp_reward': 500, 'badge_name': 'unicorn-founder'}}]
    return _enrich_with_hf_subprojects(modules)
